  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Textarea } from "@/components/ui/textarea"
import type { DataBrowserDetail, DataBrowserRowAction } from "../data-browser.types"

function getSelectValueToken(
  value: unknown,
  options: NonNullable<DataBrowserRowAction["fields"]>[number]["options"]
) {
  const index =
    options?.findIndex((option) => Object.is(option.value, value)) ?? -1

  return index >= 0 ? String(index) : ""
}

function isRequiredValueMissing(
  field: NonNullable<DataBrowserRowAction["fields"]>[number],
  value: unknown
) {
  if (field.type === "toggle") {
    return value !== true
  }

  return (
    value == null ||
    value === "" ||
    (typeof value === "string" && value.trim() === "")
  )
}

export function RowDetail<Row extends DataRow>({
  row,
  columns,
  detail,
  actions,
  actionError,
  pendingActionId,
  renderDetail,
  onRunAction,
}: {
  row: Row
  columns: DataColumn[]
  detail?: DataBrowserDetail<Row>
  actions: DataBrowserRowAction<Row>[]
  actionError?: string | null
  pendingActionId?: string | null
  renderDetail?: (row: Row) => React.ReactNode
  onRunAction: (action: DataBrowserRowAction<Row>, row: Row, values?: Record<string, unknown>) => void
}) {
  const [actionValues, setActionValues] = React.useState<Record<string, Record<string, unknown>>>({})
  const [fieldErrors, setFieldErrors] = React.useState<
    Record<string, Record<string, string>>
  >({})
  const [confirmationActionId, setConfirmationActionId] = React.useState<
    string | null
  >(null)
  const idPrefix = React.useId()
  const resolvedPendingActionId = pendingActionId ?? null

  function setActionValue(actionId: string, fieldName: string, value: unknown) {
    setActionValues((current) => ({
      ...current,
      [actionId]: {
        ...current[actionId],
        [fieldName]: value,
      },
    }))
    setFieldErrors((current) => {
      const actionFieldErrors = current[actionId]

      if (!actionFieldErrors?.[fieldName]) {
        return current
      }

      const remainingErrors = { ...actionFieldErrors }
      delete remainingErrors[fieldName]

      return {
        ...current,
        [actionId]: remainingErrors,
      }
    })
  }

  function validateAction(action: DataBrowserRowAction<Row>) {
    const values = actionValues[action.id] ?? {}
    const nextErrors: Record<string, string> = {}

    for (const field of action.fields ?? []) {
      if (field.required && isRequiredValueMissing(field, values[field.name])) {
        nextErrors[field.name] = `${field.label} is required.`
      }
    }

    setFieldErrors((current) => ({
      ...current,
      [action.id]: nextErrors,
    }))

    return Object.keys(nextErrors).length === 0
  }

  function submitAction(
    event: React.FormEvent<HTMLFormElement>,
    action: DataBrowserRowAction<Row>
  ) {
    event.preventDefault()

    if (resolvedPendingActionId !== null || !validateAction(action)) {
      return
    }

    if (action.requiresConfirmation) {
      setConfirmationActionId(action.id)
      return
    }

    onRunAction(action, row, actionValues[action.id] ?? {})
  }

  const confirmationAction = confirmationActionId
    ? actions.find((action) => action.id === confirmationActionId)
    : undefined

  if (renderDetail) {
    return <>{renderDetail(row)}</>
  }

  const detailFields = new Set(detail?.fields ?? [])
  const visibleColumns = columns.filter(
    (column) =>
      !column.hidden &&
      (detailFields.size === 0 || detailFields.has(column.key))
  )

  return (
    <div className="flex flex-col gap-4">
      <dl className="grid gap-3 sm:grid-cols-2">
        {visibleColumns.map((column) => {
          const formattedValue = formatDataCell(row, column)

          return (
            <div key={column.key} className="rounded-md border bg-muted/30 p-3">
              <dt className="text-xs font-medium text-muted-foreground">{column.label}</dt>
              <dd className="mt-1 break-words text-sm font-medium leading-6">
                {formattedValue === "" ? "-" : formattedValue}
              </dd>
            </div>
          )
        })}
      </dl>
      {actionError ? (
        <div
          role="alert"
          className="rounded-md border border-destructive/20 bg-destructive/5 p-3 text-sm text-destructive"
        >
          {actionError}
        </div>
      ) : null}
      {actions.length > 0 ? (
        <div className="flex flex-col gap-3">
          {actions.map((action) => {
            const values = actionValues[action.id] ?? {}
            const actionFieldErrors = fieldErrors[action.id] ?? {}
            const isPending = resolvedPendingActionId === action.id
            const hasPendingAction = resolvedPendingActionId !== null

            return (
              <div key={action.id} className="rounded-md border p-3">
                <form
                  className="flex flex-col gap-3"
                  aria-label={`${action.label} action`}
                  aria-busy={isPending || undefined}
                  onSubmit={(event) => submitAction(event, action)}
                >
                  <p className="text-sm font-medium">{action.label}</p>
                  {action.description ? (
                    <p className="text-xs text-muted-foreground">
                      {action.description}
                    </p>
                  ) : null}
                  <fieldset
                    disabled={hasPendingAction}
                    className="flex min-w-0 flex-col gap-3 border-0 p-0"
                  >
                    {action.fields?.map((field) => {
                      const controlId = `${idPrefix}-${action.id}-${field.name}`
                      const labelId = `${controlId}-label`
                      const errorId = `${controlId}-error`
                      const fieldError = actionFieldErrors[field.name]
                      const fieldValue = values[field.name]

                      return (
                        <div
                          key={field.name}
                          className="flex flex-col gap-1"
                          data-invalid={fieldError ? true : undefined}
                        >
                          {field.type === "toggle" ? (
                            <label
                              className="flex items-center gap-2 text-xs font-medium"
                              htmlFor={controlId}
                            >
                              <input
                                id={controlId}
                                type="checkbox"
                                className="size-4"
                                checked={fieldValue === true}
                                aria-invalid={fieldError ? true : undefined}
                                aria-describedby={
                                  fieldError ? errorId : undefined
                                }
                                aria-required={field.required || undefined}
                                onChange={(event) =>
                                  setActionValue(
                                    action.id,
                                    field.name,
                                    event.target.checked
                                  )
                                }
                              />
                              <span>
                                {field.label}
                                {field.required ? (
                                  <span aria-hidden="true"> *</span>
                                ) : null}
                              </span>
                            </label>
                          ) : (
                            <>
                              <label
                                id={labelId}
                                htmlFor={controlId}
                                className="text-xs font-medium"
                              >
                                {field.label}
                                {field.required ? (
                                  <span aria-hidden="true"> *</span>
                                ) : null}
                              </label>
                              {field.type === "textarea" ? (
                                <Textarea
                                  id={controlId}
                                  value={
                                    typeof fieldValue === "string"
                                      ? fieldValue
                                      : ""
                                  }
                                  aria-invalid={fieldError ? true : undefined}
                                  aria-describedby={
                                    fieldError ? errorId : undefined
                                  }
                                  aria-required={field.required || undefined}
                                  onChange={(event) =>
                                    setActionValue(
                                      action.id,
                                      field.name,
                                      event.target.value
                                    )
                                  }
                                />
                              ) : field.type === "select" ? (
                                <Select
                                  value={getSelectValueToken(
                                    fieldValue,
                                    field.options
                                  )}
                                  disabled={hasPendingAction}
                                  onValueChange={(token) => {
                                    const option =
                                      field.options?.[Number(token)]

                                    if (option) {
                                      setActionValue(
                                        action.id,
                                        field.name,
                                        option.value
                                      )
                                    }
                                  }}
                                >
                                  <SelectTrigger
                                    id={controlId}
                                    className="w-full"
                                    aria-labelledby={labelId}
                                    aria-invalid={fieldError ? true : undefined}
                                    aria-describedby={
                                      fieldError ? errorId : undefined
                                    }
                                    aria-required={field.required || undefined}
                                  >
                                    <SelectValue placeholder={field.label} />
                                  </SelectTrigger>
                                  <SelectContent>
                                    <SelectGroup>
                                      {field.options?.map((option, index) => (
                                        <SelectItem
                                          key={`${option.label}-${index}`}
                                          value={String(index)}
                                        >
                                          {option.label}
                                        </SelectItem>
                                      ))}
                                    </SelectGroup>
                                  </SelectContent>
                                </Select>
                              ) : (
                                <Input
                                  id={controlId}
                                  type={
                                    field.type === "number"
                                      ? "number"
                                      : field.type === "date"
                                        ? "date"
                                        : "text"
                                  }
                                  step={
                                    field.type === "number" ? "any" : undefined
                                  }
                                  value={
                                    field.type === "number"
                                      ? typeof fieldValue === "number"
                                        ? String(fieldValue)
                                        : fieldValue === ""
                                          ? ""
                                          : ""
                                      : typeof fieldValue === "string"
                                        ? fieldValue
                                        : ""
                                  }
                                  aria-invalid={fieldError ? true : undefined}
                                  aria-describedby={
                                    fieldError ? errorId : undefined
                                  }
                                  aria-required={field.required || undefined}
                                  onChange={(event) => {
                                    const value = event.target.value

                                    setActionValue(
                                      action.id,
                                      field.name,
                                      field.type === "number" && value !== ""
                                        ? Number(value)
                                        : value
                                    )
                                  }}
                                />
                              )}
                            </>
                          )}
                          {fieldError ? (
                            <p
                              id={errorId}
                              className="text-xs text-destructive"
                            >
                              {fieldError}
                            </p>
                          ) : null}
                        </div>
                      )
                    })}
                    <Button
                      type="submit"
                      disabled={hasPendingAction}
                      variant={
                        action.variant === "destructive"
                          ? "destructive"
                          : "default"
                      }
                      size="sm"
                    >
                      {isPending ? "Running..." : action.label}
                    </Button>
                  </fieldset>
                </form>
              </div>
            )
          })}
        </div>
      ) : null}
      <Dialog
        open={Boolean(confirmationAction)}
        onOpenChange={(open) => {
          if (!open) {
            setConfirmationActionId(null)
          }
        }}
      >
        {confirmationAction ? (
          <DialogContent showCloseButton={false}>
            <DialogHeader>
              <DialogTitle>Confirm {confirmationAction.label}</DialogTitle>
              <DialogDescription>
                Are you sure you want to run {confirmationAction.label} for this
                row?
              </DialogDescription>
            </DialogHeader>
            <DialogFooter>
              <DialogClose asChild>
                <Button
                  type="button"
                  variant="outline"
                  disabled={resolvedPendingActionId !== null}
                >
                  Cancel
                </Button>
              </DialogClose>
              <Button
                type="button"
                variant={
                  confirmationAction.variant === "destructive"
                    ? "destructive"
                    : "default"
                }
                disabled={resolvedPendingActionId !== null}
                onClick={() => {
                  if (resolvedPendingActionId !== null) {
                    return
                  }

                  setConfirmationActionId(null)
                  onRunAction(
                    confirmationAction,
                    row,
                    actionValues[confirmationAction.id] ?? {}
                  )
                }}
              >
                Confirm {confirmationAction.label}
              </Button>
            </DialogFooter>
          </DialogContent>
        ) : null}
      </Dialog>
    </div>
  )
}

import {
  formatDataCell,
  type DataColumn,
  type DataRow,
} from "@/lib/fable-ui/core"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { CellAvatar, isAvatarFieldKey } from "../lib/cell-avatar"
import { getDataBrowserRowId } from "../lib/get-row-id"

function getColumnMinWidth(column: DataColumn, isFirstColumn: boolean) {
  if (typeof column.width === "number") {
    return column.width
  }

  if (typeof column.width === "string") {
    const parsed = column.width.endsWith("px")
      ? Number.parseInt(column.width, 10)
      : Number.NaN
    return Number.isFinite(parsed) ? parsed : 160
  }

  if (isFirstColumn) {
    return 220
  }

  if (column.type === "currency" || column.type === "number") {
    return 132
  }

  if (column.type === "date") {
    return 140
  }

  if (column.type === "datetime") {
    return 180
  }

  if (column.type === "boolean" || column.type === "badge") {
    return 120
  }

  return Math.max(144, Math.min(260, column.label.length * 12 + 72))
}

function getColumnWidth(column: DataColumn, minWidth: number) {
  if (typeof column.width === "number") {
    return `${column.width}px`
  }

  return column.width ?? `${minWidth}px`
}

function getAlignClass(align: DataColumn["align"]) {
  if (align === "right") {
    return "text-end"
  }

  if (align === "center") {
    return "text-center"
  }

  return "text-start"
}

export function TableView<Row extends DataRow>({
  columns,
  rows,
  entityLabel,
  isDisabled,
  onViewRow,
}: {
  columns: DataColumn[]
  rows: Row[]
  entityLabel: string
  isDisabled?: boolean
  onViewRow?: (row: Row) => void
}) {
  const visibleColumns = columns.filter((column) => !column.hidden)
  const columnWidths = visibleColumns.map((column, index) =>
    getColumnMinWidth(column, index === 0)
  )
  const actionColumnWidth = onViewRow ? 112 : 0
  const tableMinWidth = Math.max(
    visibleColumns.length
      ? columnWidths.reduce((total, width) => total + width, actionColumnWidth)
      : 320,
    640
  )
  const colSpan = Math.max(1, visibleColumns.length + (onViewRow ? 1 : 0))

  return (
    <div
      className="min-h-0 overflow-auto rounded-md border scrollbar-pretty max-h-[min(60vh,36rem)]"
      role="region"
      tabIndex={0}
      aria-label={`${entityLabel} table`}
    >
      <table
        className="w-full table-auto text-sm"
        style={{ minWidth: tableMinWidth }}
      >
        <thead className="bg-muted/60">
          <tr>
            {visibleColumns.map((column, index) => (
              <th
                key={column.key}
                className={cn(
                  "px-3 py-2 font-medium whitespace-nowrap",
                  getAlignClass(column.align)
                )}
                data-align={column.align ?? "left"}
                style={{
                  minWidth: columnWidths[index],
                  width: getColumnWidth(column, columnWidths[index]),
                }}
              >
                {column.label}
              </th>
            ))}
            {onViewRow ? (
              <th className="w-28 px-3 py-2 text-end font-medium">View</th>
            ) : null}
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 ? (
            <tr>
              <td
                className="px-3 py-8 text-center text-muted-foreground"
                colSpan={colSpan}
              >
                No {entityLabel} to display.
              </td>
            </tr>
          ) : (
            rows.map((row, index) => (
              <tr key={getDataBrowserRowId(row, index)} className="border-t">
                {visibleColumns.map((column, columnIndex) => {
                  const rowId = getDataBrowserRowId(row, index)
                  const formattedValue = formatDataCell(row, column)
                  const cellValue =
                    columnIndex === 0 && isAvatarFieldKey(column.key)
                      ? ""
                      : formattedValue

                  return (
                    <td
                      key={`${rowId}-${column.key}`}
                      className={cn(
                        "px-3 py-2 align-middle",
                        getAlignClass(column.align)
                      )}
                      style={{
                        minWidth: columnWidths[columnIndex],
                        width: getColumnWidth(
                          column,
                          columnWidths[columnIndex]
                        ),
                      }}
                    >
                      {columnIndex === 0 ? (
                        <div className="flex min-w-0 items-center gap-2">
                          <CellAvatar row={row} />
                          <span className="min-w-0 truncate" title={cellValue || undefined}>
                            {cellValue}
                          </span>
                        </div>
                      ) : (
                        <span
                          className="block min-w-0 truncate"
                          title={formattedValue || undefined}
                        >
                          {formattedValue}
                        </span>
                      )}
                    </td>
                  )
                })}
                {onViewRow ? (
                  <td className="px-3 py-2 text-end">
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      disabled={isDisabled}
                      onClick={() => onViewRow(row)}
                    >
                      View
                    </Button>
                  </td>
                ) : null}
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  )
}

import { SearchIcon } from "lucide-react"

import type { DataFilter, DataSort, SortState } from "@/lib/fable-ui/core"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"

function getOptionValue(option: string | { value: string | number | boolean }) {
  return typeof option === "string" ? option : String(option.value)
}

function getOptionLabel(option: string | { label: string }) {
  return typeof option === "string" ? option : option.label
}

export function DataBrowserToolbar({
  search,
  searchPlaceholder,
  filters,
  filterValues,
  sortOptions,
  sort,
  isDisabled,
  onSearchChange,
  onFilterChange,
  onSortChange,
  onClearFilters,
}: {
  search: string
  searchPlaceholder: string
  filters: DataFilter[]
  filterValues: Record<string, unknown>
  sortOptions: DataSort[]
  sort?: SortState
  isDisabled?: boolean
  onSearchChange: (value: string) => void
  onFilterChange: (key: string, value: unknown) => void
  onSortChange: (sort?: SortState) => void
  onClearFilters: () => void
}) {
  const hasFilters = Object.values(filterValues).some(
    (value) => value != null && value !== ""
  )

  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-col gap-2 sm:flex-row">
        <label className="relative flex-1">
          <span className="sr-only">{searchPlaceholder}</span>
          <SearchIcon className="pointer-events-none absolute top-1/2 start-3 size-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={search}
            placeholder={searchPlaceholder}
            disabled={isDisabled}
            aria-label={searchPlaceholder}
            className="ps-9"
            onChange={(event) => onSearchChange(event.target.value)}
          />
        </label>
        {sortOptions.length > 0 ? (
          <Select
            value={sort ? `${sort.key}:${sort.direction}` : ""}
            disabled={isDisabled}
            onValueChange={(value) => {
              if (!value) {
                onSortChange(undefined)
                return
              }

              const [key, direction] = value.split(":")
              onSortChange({
                key,
                direction: direction === "desc" ? "desc" : "asc",
              })
            }}
          >
            <SelectTrigger className="w-full sm:w-48" aria-label="Sort rows">
              <SelectValue placeholder="Sort" />
            </SelectTrigger>
            <SelectContent>
              <SelectGroup>
                {sortOptions.flatMap((option) =>
                  (option.directions ?? ["asc", "desc"]).map((direction) => (
                    <SelectItem
                      key={`${option.key}:${direction}`}
                      value={`${option.key}:${direction}`}
                    >
                      {option.label} {direction === "asc" ? "asc" : "desc"}
                    </SelectItem>
                  ))
                )}
              </SelectGroup>
            </SelectContent>
          </Select>
        ) : null}
      </div>
      {filters.length > 0 ? (
        <div className="flex flex-wrap gap-2">
          {filters.map((filter) => {
            if (filter.type === "select" && filter.options?.length) {
              return (
                <Select
                  key={filter.key}
                  value={String(filterValues[filter.key] ?? "")}
                  disabled={isDisabled}
                  onValueChange={(value) => onFilterChange(filter.key, value)}
                >
                  <SelectTrigger
                    className="w-full sm:w-44"
                    aria-label={filter.label}
                  >
                    <SelectValue placeholder={filter.label} />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectGroup>
                      {filter.options.map((option) => (
                        <SelectItem
                          key={getOptionValue(option)}
                          value={getOptionValue(option)}
                        >
                          {getOptionLabel(option)}
                        </SelectItem>
                      ))}
                    </SelectGroup>
                  </SelectContent>
                </Select>
              )
            }

            return (
              <Input
                key={filter.key}
                value={String(filterValues[filter.key] ?? "")}
                placeholder={filter.label}
                disabled={isDisabled}
                aria-label={filter.label}
                className="w-full sm:w-44"
                onChange={(event) =>
                  onFilterChange(filter.key, event.target.value)
                }
              />
            )
          })}
          {hasFilters ? (
            <Button
              type="button"
              variant="ghost"
              size="sm"
              disabled={isDisabled}
              onClick={onClearFilters}
            >
              Clear
            </Button>
          ) : null}
        </div>
      ) : null}
    </div>
  )
}

"use client"

import { useState } from "react"

import {
  getDataValue,
  normalizeDataValue,
  type DataRow,
} from "@/lib/fable-ui/core"
import { cn } from "@/lib/utils"

const avatarFieldNames = new Set([
  "avatar",
  "avatarurl",
  "image",
  "imageurl",
  "picture",
  "pictureurl",
  "photo",
  "photourl",
])

const labelFieldNames = [
  "name",
  "fullname",
  "displayname",
  "title",
  "label",
  "customer",
  "username",
  "email",
]

function normalizeKey(key: string) {
  return key.replace(/[^a-z0-9]/gi, "").toLowerCase()
}

export function isAvatarFieldKey(key: string) {
  return avatarFieldNames.has(normalizeKey(key))
}

function getRowKeys(row: DataRow) {
  const keys = new Set(Object.keys(row))
  const cells = row.cells

  if (cells && typeof cells === "object" && !Array.isArray(cells)) {
    Object.keys(cells as Record<string, unknown>).forEach((key) =>
      keys.add(key)
    )
  }

  return Array.from(keys)
}

function getFirstMatchingValue(row: DataRow, keys: string[]) {
  const rowKeys = getRowKeys(row)

  for (const expectedKey of keys) {
    const key = rowKeys.find(
      (candidate) => normalizeKey(candidate) === expectedKey
    )
    const value = key ? getDataValue(row, key) : undefined

    if (value != null && normalizeDataValue(value).trim() !== "") {
      return value
    }
  }

  return undefined
}

function getImageUrl(value: unknown) {
  const text = normalizeDataValue(value).trim()

  if (!text) {
    return undefined
  }

  if (/^data:image\/[a-z0-9.+-]+[,;]/i.test(text)) {
    return text
  }

  try {
    const url = new URL(text)
    return url.protocol === "http:" || url.protocol === "https:"
      ? text
      : undefined
  } catch {
    return undefined
  }
}

function getInitials(value: unknown) {
  const text = normalizeDataValue(value).trim()

  if (!text) {
    return undefined
  }

  const initials = text
    .split(/[\s._-]+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0])
    .join("")
    .toUpperCase()

  return initials || text.slice(0, 2).toUpperCase()
}

export function getAvatarPresentation(row: DataRow) {
  const avatarValue = getFirstMatchingValue(row, Array.from(avatarFieldNames))
  const labelValue = getFirstMatchingValue(row, labelFieldNames)
  const src = getImageUrl(avatarValue)
  const initials = getInitials(labelValue)
  const label = normalizeDataValue(labelValue).trim() || "Row"

  if (!src && !initials) {
    return null
  }

  return { src, initials: initials ?? "?", label }
}

export function CellAvatar({
  row,
  className,
}: {
  row: DataRow
  className?: string
}) {
  const [imageFailed, setImageFailed] = useState(false)
  const avatar = getAvatarPresentation(row)

  if (!avatar) {
    return null
  }

  return (
    <span
      className={cn(
        "flex size-8 shrink-0 items-center justify-center overflow-hidden rounded-full bg-muted text-xs font-medium text-muted-foreground",
        className
      )}
      aria-hidden="true"
    >
      {avatar.src && !imageFailed ? (
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={avatar.src}
          alt=""
          className="size-full object-cover"
          loading="lazy"
          onError={() => setImageFailed(true)}
        />
      ) : (
        avatar.initials
      )}
    </span>
  )
}

import { getDataValue, type DataColumn, type DataFilter, type DataRow, type DataSort } from "@/lib/fable-ui/core"

const fallbackFilterKeys = new Set(["status", "type", "category", "role"])

export function getFallbackFilters(rows: DataRow[], columns: DataColumn[]): DataFilter[] {
  return columns
    .filter((column) => column.filterable || fallbackFilterKeys.has(column.key))
    .map((column) => {
      const values = Array.from(
        new Set(
          rows
            .map((row) => getDataValue(row, column.key))
            .filter((value) => value != null && value !== "")
            .map(String),
        ),
      ).slice(0, 20)

      return {
        key: column.key,
        label: column.label,
        type: values.length > 0 ? "select" : "text",
        options: values,
      } satisfies DataFilter
    })
}

export function getFallbackSortOptions(columns: DataColumn[]): DataSort[] {
  return columns
    .filter((column) => column.sortable !== false)
    .map((column) => ({
      key: column.key,
      label: column.label,
      directions: ["asc", "desc"],
    }))
}

import { getRowId as getCoreRowId, type DataRow } from "@/lib/fable-ui/core"

export function getDataBrowserRowId(row: DataRow, index = 0) {
  return getCoreRowId(row) ?? String(index)
}
